import{_ as o,o as c,c as d,a0 as l}from"./chunks/framework.C7-mHYcV.js";const h=JSON.parse('{"title":"Checkbox & Radio 组件兼容 Vapor 与 VDOM 双模式设计规格","description":"","frontmatter":{},"headers":[],"relativePath":"superpowers/specs/2026-08-17-checkbox-radio-vapor-vdom-design.md","filePath":"superpowers/specs/2026-08-17-checkbox-radio-vapor-vdom-design.md"}'),a={name:"superpowers/specs/2026-08-17-checkbox-radio-vapor-vdom-design.md"};function i(r,e,t,u,p,s){return c(),d("div",null,[...e[0]||(e[0]=[l('<h1 id="checkbox-radio-组件兼容-vapor-与-vdom-双模式设计规格" tabindex="-1">Checkbox &amp; Radio 组件兼容 Vapor 与 VDOM 双模式设计规格 <a class="header-anchor" href="#checkbox-radio-组件兼容-vapor-与-vdom-双模式设计规格" aria-label="Permalink to &quot;Checkbox &amp; Radio 组件兼容 Vapor 与 VDOM 双模式设计规格&quot;">​</a></h1><h2 id="_1-概述" tabindex="-1">1. 概述 <a class="header-anchor" href="#_1-概述" aria-label="Permalink to &quot;1. 概述&quot;">​</a></h2><p>本项目 uni-app X 需在两种编译运行模式下运行良好：</p><ol><li><strong>VDOM 模式</strong>：基于虚拟 DOM 的传统渲染模式。</li><li><strong>Vapor 模式</strong>：基于 Vue Vapor 机制的无虚拟 DOM 高性能模式。</li></ol><p>当前 <code>up-checkbox</code> / <code>up-checkbox-group</code> 与 <code>up-radio</code> / <code>up-radio-group</code> 在跨组件通信中存在对 <code>$parent</code>、<code>$children</code>、<code>$callMethod</code> 和 Options API <code>mixins</code> 的强依赖，导致在 Vapor 模式下父子状态无法同步。</p><p>本设计将上述两组组件重构为基于 Vue 3 核心 <code>provide / inject</code> 响应式状态下发与事件通知架构，同时保持全部原有 API、props、插槽及样式兼容。</p><hr><h2 id="_2-架构设计" tabindex="-1">2. 架构设计 <a class="header-anchor" href="#_2-架构设计" aria-label="Permalink to &quot;2. 架构设计&quot;">​</a></h2><h3 id="_2-1-数据流与通信机制" tabindex="-1">2.1 数据流与通信机制 <a class="header-anchor" href="#_2-1-数据流与通信机制" aria-label="Permalink to &quot;2.1 数据流与通信机制&quot;">​</a></h3><ul><li><strong>父级 Group（<code>up-radio-group</code> / <code>up-checkbox-group</code>）</strong>： <ul><li>维护自身 <code>props</code>（<code>modelValue</code> 等）。</li><li>通过 <code>provide(GROUP_PROPS_KEY, parentData)</code> 下发响应式只读状态。</li><li>通过 <code>provide(GROUP_HANDLER_KEY, handler)</code> 下发回调函数。</li><li>通过 <code>emit(&#39;update:modelValue&#39;, val)</code> 与 <code>emit(&#39;change&#39;, val)</code> 响应外界 <code>v-model</code>。</li></ul></li><li><strong>子级 Item（<code>up-radio</code> / <code>up-checkbox</code>）</strong>： <ul><li>通过 <code>inject(GROUP_PROPS_KEY)</code> 获取父级配置。</li><li><code>isChecked</code>、<code>elDisabled</code>、<code>elSize</code>、<code>elActiveColor</code> 等属性均通过 <code>computed</code> 响应式派生。</li><li>点击时优先调用 <code>inject(GROUP_HANDLER_KEY)</code> 回调通知父组件，父组件更新 <code>modelValue</code> 后子组件自动触发响应式重绘。</li><li>如果未处于 Group 容器内（如单独使用 <code>usedAlone</code>），则降级为组件内部本地 <code>ref</code> 驱动。</li></ul></li></ul><hr><h2 id="_3-组件详细设计" tabindex="-1">3. 组件详细设计 <a class="header-anchor" href="#_3-组件详细设计" aria-label="Permalink to &quot;3. 组件详细设计&quot;">​</a></h2><h3 id="_3-1-up-radio-group" tabindex="-1">3.1 <code>up-radio-group</code> <a class="header-anchor" href="#_3-1-up-radio-group" aria-label="Permalink to &quot;3.1 `up-radio-group`&quot;">​</a></h3><ul><li>使用 <code>&lt;script setup lang=&quot;uts&quot;&gt;</code>。</li><li>Props：<code>modelValue</code>, <code>disabled</code>, <code>shape</code>, <code>activeColor</code>, <code>inactiveColor</code>, <code>name</code>, <code>size</code>, <code>placement</code>, <code>label</code>, <code>labelColor</code>, <code>labelSize</code>, <code>labelDisabled</code>, <code>iconColor</code>, <code>iconSize</code>, <code>borderBottom</code>, <code>iconPlacement</code>, <code>customStyle</code>。</li><li>Emits：<code>[&#39;update:modelValue&#39;, &#39;change&#39;]</code>。</li><li>Provide 键名： <ul><li><code>&#39;upRadioGroupProps&#39;</code>: <code>ComputedRef&lt;UTSJSONObject&gt;</code></li><li><code>&#39;upRadioGroupChange&#39;</code>: <code>(name: any) =&gt; void</code></li></ul></li></ul><h3 id="_3-2-up-radio" tabindex="-1">3.2 <code>up-radio</code> <a class="header-anchor" href="#_3-2-up-radio" aria-label="Permalink to &quot;3.2 `up-radio`&quot;">​</a></h3><ul><li>使用 <code>&lt;script setup lang=&quot;uts&quot;&gt;</code>。</li><li>Props：<code>name</code>, <code>shape</code>, <code>disabled</code>, <code>labelDisabled</code>, <code>activeColor</code>, <code>inactiveColor</code>, <code>iconSize</code>, <code>labelSize</code>, <code>label</code>, <code>size</code>, <code>iconColor</code>, <code>labelColor</code>, <code>customStyle</code>, <code>usedAlone</code>。</li><li>Emits：<code>[&#39;change&#39;, &#39;update:checked&#39;]</code>。</li><li>Inject： <ul><li><code>&#39;upRadioGroupProps&#39;</code></li><li><code>&#39;upRadioGroupChange&#39;</code></li></ul></li><li>状态派生： <ul><li><code>isChecked</code>: 若存在 group 则判断 <code>parentProps.value[&#39;modelValue&#39;] == props.name</code>；否则使用本地 <code>selfChecked</code>。</li></ul></li></ul><h3 id="_3-3-up-checkbox-group" tabindex="-1">3.3 <code>up-checkbox-group</code> <a class="header-anchor" href="#_3-3-up-checkbox-group" aria-label="Permalink to &quot;3.3 `up-checkbox-group`&quot;">​</a></h3><ul><li>使用 <code>&lt;script setup lang=&quot;uts&quot;&gt;</code>。</li><li>Props：<code>name</code>, <code>modelValue</code>, <code>shape</code>, <code>disabled</code>, <code>activeColor</code>, <code>inactiveColor</code>, <code>size</code>, <code>placement</code>, <code>labelSize</code>, <code>labelColor</code>, <code>labelDisabled</code>, <code>iconColor</code>, <code>iconSize</code>, <code>iconPlacement</code>, <code>borderBottom</code>, <code>customStyle</code>。</li><li>Emits：<code>[&#39;update:modelValue&#39;, &#39;change&#39;]</code>。</li><li>Provide 键名： <ul><li><code>&#39;upCheckboxGroupProps&#39;</code>: <code>ComputedRef&lt;UTSJSONObject&gt;</code></li><li><code>&#39;upCheckboxGroupToggle&#39;</code>: <code>(name: string, checked: boolean) =&gt; void</code></li></ul></li></ul><h3 id="_3-4-up-checkbox" tabindex="-1">3.4 <code>up-checkbox</code> <a class="header-anchor" href="#_3-4-up-checkbox" aria-label="Permalink to &quot;3.4 `up-checkbox`&quot;">​</a></h3><ul><li>使用 <code>&lt;script setup lang=&quot;uts&quot;&gt;</code>。</li><li>Props：<code>name</code>, <code>shape</code>, <code>size</code>, <code>checked</code>, <code>disabled</code>, <code>activeColor</code>, <code>inactiveColor</code>, <code>iconSize</code>, <code>iconColor</code>, <code>label</code>, <code>labelColor</code>, <code>labelSize</code>, <code>labelDisabled</code>, <code>customStyle</code>, <code>usedAlone</code>。</li><li>Emits：<code>[&#39;change&#39;, &#39;update:checked&#39;]</code>。</li><li>Inject： <ul><li><code>&#39;upCheckboxGroupProps&#39;</code></li><li><code>&#39;upCheckboxGroupToggle&#39;</code></li></ul></li><li>状态派生： <ul><li><code>isChecked</code>: 若存在 group 则判断 <code>(parentProps.value[&#39;modelValue&#39;] as any[]).includes(props.name)</code>；否则使用本地 <code>selfChecked</code>。</li></ul></li></ul><hr><h2 id="_4-验证计划" tabindex="-1">4. 验证计划 <a class="header-anchor" href="#_4-验证计划" aria-label="Permalink to &quot;4. 验证计划&quot;">​</a></h2><ol><li>运行 checkbox demo 页面（<code>src/sub/uview-ultra/demos/checkbox/checkbox.uvue</code>）。</li><li>运行 radio demo 页面（<code>src/sub/uview-ultra/demos/radio/radio.uvue</code>）。</li><li>检查控制台与交互日志，验证全平台 UTS 编译无类型与语法报错。</li></ol>',23)])])}const b=o(a,[["render",i]]);export{h as __pageData,b as default};
